package br.com.admeclesial.interfaces.rest.financeiro; import br.com.admeclesial.application.financeiro.ContaFinanceiraApplicationService; import br.com.admeclesial.domain.financeiro.*; import org.springframework.web.bind.annotation.*; import java.util.*; @RestController @RequestMapping("/api/v1/contas-financeiras") public class ContaFinanceiraRestController { final ContaFinanceiraApplicationService s; public ContaFinanceiraRestController(ContaFinanceiraApplicationService s){this.s=s;} @GetMapping public List<ContaFinanceira> listar(){return s.listar();} @GetMapping("/{uuid}") public ContaFinanceira buscar(@PathVariable UUID uuid){return s.buscar(uuid);} @PostMapping public ContaFinanceira criar(@RequestParam UUID organizacaoEclesialUuid,@RequestParam String nome,@RequestParam TipoContaFinanceira tipo,@RequestParam(defaultValue="true") boolean ativo){return s.salvar(null,organizacaoEclesialUuid,nome,tipo,null,null,null,ativo);} }